contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address spender, uint256 value) public {
        require(value != 0);
        require(spender != address(0));

        bool firstApprove = c.approve(spender, value); if (__ESBMC_reverted()) return;
        uint256 allowanceAfter = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        bool secondApprove;
        bool s = c.approve(spender, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { secondApprove = false; } else { secondApprove = s; }

        uint256 allowanceAfterSecond = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        bool zeroApprove = c.approve(spender, 0); if (__ESBMC_reverted()) return;
        uint256 allowanceAfterZero = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        assert(firstApprove && allowanceAfter == value &&
               !secondApprove && allowanceAfterSecond == value &&
               zeroApprove && allowanceAfterZero == 0);
    }
}

